import { after } from 'next/server'

async function logPageView(path: string) {
  // Simulate sending a page view to an analytics service
  console.log(`Analytics: page view for ${path}`)
}

export default function Home() {
  after(() => {
    logPageView('/')
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>Thanks for visiting. Your page view has been logged.</p>
    </main>
  )
}

